"""
Simulacion de la formulacion adimensional exportada por el nucleo de adimensionalizacion.
Metodo de lineas: diferencias centradas de segundo orden, condiciones declaradas
resueltas en cada evaluacion (Newton) e integracion BDF. Misma discretizacion que el
estudio del nucleo; los valores de los parametros estan en SI.
"""
import numpy as np
from scipy.integrate import solve_ivp
from scipy.special import erf

P = {'D': 1e-09, 'ell': 0.01, 'c0': 50.0, 'tf': 1.0, 'x_ref': 0.01, 'c_ref': 50.0, 't_ref': 100000.0}
CAMPOS = ['c_ad']
DERIVADAS = {'c_ad|x_ad|2': ('c_ad', 'x_ad', 2)}
N = 21
PERIODICA = False
XI_TODOS = np.linspace(0.0, 1.0, N, endpoint=not PERIODICA)
H = XI_TODOS[1] - XI_TODOS[0]
INCOGNITAS = {'desde': [('valor', 'c_ad')], 'hasta': [('valor', 'c_ad')]}
DIRICHLET = {'desde': ['c_ad'], 'hasta': ['c_ad']}
ORDENES = {'c_ad': 2}

def rhs_campo(campo, U, XI, T, D):
    if campo == 'c_ad':
        return (- (-1.0) * (1.0*D('c_ad|x_ad|2'))) / 1.0

def residuos_extremo(lado, U, XI, T, D):
    r = []
    if lado == 'desde':
        r.append((1.0) * (1.0*U['c_ad']))  # condicion izq
    if lado == 'hasta':
        r.append((1.0) * (1.0*U['c_ad']))  # condicion der
    return np.array(r, dtype=complex if any(np.iscomplexobj(v) for v in U.values()) else float)

INDICES = {}
_k = 0
for _c in CAMPOS:
    _nodos = [i for i in range(N) if not ((i == 0 and _c in DIRICHLET["desde"]) or (i == N - 1 and _c in DIRICHLET["hasta"]))]
    INDICES[_c] = (_k, _nodos)
    _k += len(_nodos)
TAM = _k
PREVIO = {"desde": np.zeros(len(INCOGNITAS["desde"])), "hasta": np.zeros(len(INCOGNITAS["hasta"]))}

def _resolver_extremo(lado, U, t):
    incogs = INCOGNITAS[lado]
    nodo = 0 if lado == "desde" else N - 1
    def residuos(x):
        V = {c: U[c].astype(complex if np.iscomplexobj(x) else float).copy() for c in CAMPOS}
        fant = {}
        for (tipo, c), v in zip(incogs, x):
            if tipo == "valor":
                V[c][nodo] = v
            else:
                fant[c] = v
        def D(clave):
            c = DERIVADAS[clave][0]
            arr = V[c]
            if lado == "desde":
                g = fant.get(c, 2 * arr[0] - arr[1])
                return (arr[1] - g) / (2 * H)
            g = fant.get(c, 2 * arr[-1] - arr[-2])
            return (g - arr[-2]) / (2 * H)
        return residuos_extremo(lado, {c: V[c][nodo] for c in CAMPOS}, XI_TODOS[nodo], t, D)
    x = PREVIO[lado].astype(float)
    for _ in range(30):
        r = residuos(x)
        if np.max(np.abs(r)) < 1e-13 * max(1.0, np.max(np.abs(x))):
            break
        J = np.zeros((len(x), len(x)))
        for j in range(len(x)):
            z = x.astype(complex)
            z[j] += 1e-30j
            J[:, j] = np.imag(residuos(z)) / 1e-30
        x = x + np.linalg.solve(J, -r)
    PREVIO[lado] = x
    return x

def _arreglos(y, t):
    U = {}
    for c in CAMPOS:
        k, nodos = INDICES[c]
        arr = np.empty(N)
        arr[nodos] = y[k:k + len(nodos)]
        if 0 not in nodos:
            arr[0] = arr[1]
        if N - 1 not in nodos:
            arr[-1] = arr[-2]
        U[c] = arr
    fantasmas = {}
    for lado in ("desde", "hasta"):
        if not INCOGNITAS[lado]:
            continue
        x = _resolver_extremo(lado, U, t)
        for (tipo, c), v in zip(INCOGNITAS[lado], x):
            if tipo == "valor":
                U[c][0 if lado == "desde" else -1] = v
            else:
                fantasmas[(c, lado)] = v
    ext = {}
    for c in CAMPOS:
        arr = U[c]
        if PERIODICA:
            ext[c] = np.concatenate([arr[-1:], arr, arr[:1]])
            continue
        izq = fantasmas.get((c, "desde"), 2 * arr[0] - arr[1] if ORDENES[c] else arr[0])
        der = fantasmas.get((c, "hasta"), 2 * arr[-1] - arr[-2] if ORDENES[c] else arr[-1])
        ext[c] = np.concatenate([[izq], arr, [der]])
    return U, ext

def rhs(t, y):
    U, ext = _arreglos(y, t)
    dy = np.empty(TAM)
    for c in CAMPOS:
        k, nodos = INDICES[c]
        idx = np.asarray(nodos) + 1
        def D(clave):
            campo, _, orden = DERIVADAS[clave]
            e = ext[campo]
            if orden == 1:
                return (e[idx + 1] - e[idx - 1]) / (2 * H)
            return (e[idx + 1] - 2 * e[idx] + e[idx - 1]) / H ** 2
        dy[k:k + len(nodos)] = rhs_campo(c, {d: U[d][nodos] for d in CAMPOS}, XI_TODOS[nodos], t, D)
    return dy

def integrar(tf, muestras):
    U0 = condicion_inicial()
    y0 = np.zeros(TAM)
    for c in CAMPOS:
        k, nodos = INDICES[c]
        y0[k:k + len(nodos)] = np.broadcast_to(U0[c], (N,))[nodos]
    return solve_ivp(rhs, (0.0, tf), y0, method="BDF", t_eval=np.linspace(0.0, tf, muestras), rtol=1e-6, atol=1e-9)

def perfiles(sol):
    r = {c: [] for c in CAMPOS}
    for j in range(sol.y.shape[1]):
        U, _ = _arreglos(sol.y[:, j], sol.t[j])
        for c in CAMPOS:
            r[c].append(U[c].copy())
    return r

def condicion_inicial():
    U0 = {}
    XI = XI_TODOS if 'XI_TODOS' in globals() else 0.0
    T = 0.0
    D = lambda clave: 0.0
    r = []
    for x in (0.0, 1.0):
        U = {'c_ad': x * np.ones_like(np.atleast_1d(XI), dtype=float)}
        r.append(np.atleast_1d((1.0) * (1.0*U['c_ad']) + (-1.0) * (1.0*np.sin((3.141592653589793*(P['ell'])**-1*XI*P['x_ref'])))) * np.ones_like(np.atleast_1d(XI), dtype=float))
    U0['c_ad'] = -r[0] / (r[1] - r[0])
    return U0

TF, MUESTRAS = 0.2, 6
sol = integrar(TF, MUESTRAS)
if __name__ == '__main__':
    print('estado:', sol.message)
    for c, perfil in perfiles(sol).items():
        print(c, 'en tau final:', np.round(perfil[-1], 6))
